class _KdNode {
  final List<double> point;
  final int depth;
  _KdNode? left;
  _KdNode? right;
  _KdNode(this.point, this.depth);
}

_KdNode? _buildKdTree(List<List<double>> points, int depth) {
  if (points.isEmpty) return null;
  final axis = depth % 2;
  points.sort((a, b) => a[axis].compareTo(b[axis]));
  final mid = points.length ~/ 2;
  final node = _KdNode(points[mid], depth);
  node.left = _buildKdTree(points.sublist(0, mid), depth + 1);
  node.right = _buildKdTree(points.sublist(mid + 1), depth + 1);
  return node;
}

void _printInOrder(_KdNode? node) {
  if (node == null) return;
  _printInOrder(node.left);
  print('Depth ${node.depth}: ${node.point}');
  _printInOrder(node.right);
}

