class Complex {
  final double re;
  final double im;

  const Complex(this.re, this.im);

  factory Complex.polar(double mod, double arg) {
    return Complex(mod * math.cos(arg), mod * math.sin(arg));
  }

  Complex operator +(Complex other) {
    return Complex(re + other.re, im + other.im);
  }

  Complex operator -(Complex other) {
    return Complex(re - other.re, im - other.im);
  }

  Complex operator *(Complex other) {
    return Complex(
      re * other.re - im * other.im,
      re * other.im + im * other.re,
    );
  }

  Complex operator /(Complex other) {
    final double denominator =
        other.re * other.re + other.im * other.im;
    return Complex(
      (re * other.re + im * other.im) / denominator,
      (im * other.re - re * other.im) / denominator,
    );
  }

  Complex get conj => Complex(re, -im);

  double get arg => math.atan2(im, re);

  double get mod => math.sqrt(re * re + im * im);

  Complex get exp {
    final double factor = math.exp(re);
    return Complex(factor * math.cos(im), factor * math.sin(im));
  }

  @override
  String toString() => '$re + ${im}i';
}

